import { group, heading, paragraph } from "@/lib/wp/blocks";
import { text } from "./shared";
import type { SectionDefinition } from "./types";

export type ContentStepsProps = {
  heading?: string;
  intro?: string;
  steps?: Array<{ title: string; body: string }>;
};

/**
 * A numbered process — "how it works", in three or four steps.
 *
 * The numbers are generated by CSS counters rather than written into the
 * content. That matters for round-tripping: if a client deletes step two in
 * wp-admin, the remaining steps renumber themselves instead of reading
 * "1, 3, 4". Hard-coded numerals in the text would have to be corrected by hand
 * every time the list changed.
 */
export const ContentSteps: SectionDefinition<ContentStepsProps> = {
  key: "content-steps",
  nodeType: "ContentSteps",
  name: "How it works",
  category: "Content",
  description:
    "A numbered process in three or four steps. Numbers come from CSS, so deleting a step renumbers the rest automatically.",
  rootClass: "yp-steps",

  fields: {
    heading: { type: "text", label: "Section heading", maxChars: 60 },
    intro: { type: "text", label: "Intro line", maxChars: 150 },
    steps: {
      type: "list",
      label: "Steps",
      hint: "Three or four — beyond that it stops feeling simple",
      of: {
        title: { type: "text", label: "Step name" },
        body: { type: "text", label: "What happens" },
      },
    },
  },

  aiPrompt:
    "Describe what actually happens from the customer's side, in their order of experience — get in " +
    "touch, we do X, you receive Y. Name each step as an action. Say who does the work in each: the " +
    "point is to show how little the customer has to do.",

  sample: {
    heading: "Ordering is three steps",
    intro: "No accounts, no minimum order, and a person on the other end of it.",
    steps: [
      { title: "Tell us the occasion", body: "Call in or send a note with the date, a rough budget and anything you know they like." },
      { title: "We suggest and confirm", body: "You get options with prices within a day. Nothing is charged until you say yes." },
      { title: "We deliver or you collect", body: "Made the morning it goes out, delivered by us — not a courier." },
    ],
  },

  toGutenberg(p) {
    const steps = (p.steps ?? [])
      .filter((s) => s?.title || s?.body)
      .map((s) =>
        group(
          "yp-steps__item",
          (s.title ? heading(s.title, 3, "yp-steps__title") : "") +
            (s.body ? paragraph(s.body, "yp-steps__body") : ""),
        ),
      )
      .join("");

    const head = [
      p.heading ? heading(p.heading, 2, "yp-steps__heading") : "",
      p.intro ? paragraph(p.intro, "yp-steps__intro") : "",
    ]
      .filter(Boolean)
      .join("");

    return group("yp-steps", head + group("yp-steps__list", steps), "section");
  },

  fromGutenberg(root) {
    const el = root.querySelector(".yp-steps");
    if (!el) return null;
    return {
      heading: text(el.querySelector(".yp-steps__heading")),
      intro: text(el.querySelector(".yp-steps__intro")),
      steps: el
        .querySelectorAll(".yp-steps__item")
        .map((s) => ({
          title: text(s.querySelector(".yp-steps__title")),
          body: text(s.querySelector(".yp-steps__body")),
        }))
        .filter((s) => s.title || s.body),
    };
  },
};
